CONFIGS = [
    ("SC-on + recompute-on",   SC_ON_REC,    "#2196F3"),
    ("SC-on + recompute-off",  SC_ON_NOREC,  "#4CAF50"),
    ("SC-off + recompute-on",  SC_OFF_REC,   "#FF5722"),
    ("SC-off + recompute-off", SC_OFF_NOREC, "#9E9E9E"),
]


def main():
    parser = argparse.ArgumentParser(description="Generate reward curve figure.")
    parser.add_argument("--out-dir", default=".",
                        help="Output directory for PNG (default: .)")
    args = parser.parse_args()
    os.makedirs(args.out_dir, exist_ok=True)

    fig, ax = plt.subplots(figsize=(10, 5))
    for label, data, color in CONFIGS:
        steps  = np.array([d[0] for d in data])
        reward = np.array([d[1] for d in data])
        ax.plot(steps, reward, label=label, color=color, linewidth=2, alpha=0.9)

    ax.set_xlabel("Training Step", fontsize=12)
    ax.set_ylabel("Reward (20-step rolling mean)", fontsize=12)
    ax.set_title("Reward Curves: SC-on vs SC-off (1000 steps)", fontsize=14)
    ax.legend(fontsize=10, loc="lower right")
    ax.grid(True, alpha=0.3)
    ax.set_xlim(0, 1000)
    ax.set_ylim(0, 1.0)
    fig.tight_layout()
    out_path = os.path.join(args.out_dir, "reward_curves.png")
    fig.savefig(out_path, dpi=150)
    plt.close(fig)
    print(f"Saved: {out_path}")


if __name__ == "__main__":
    main()
